import * as React from 'react';
import { IReturnRequest } from '../models/IReturnRequest';
import { IInventoryItem } from '../models/IInventoryItem';
import {
  DetailsList,
  DetailsListLayoutMode,
  SelectionMode,
  IColumn,
  DefaultButton,
  PrimaryButton,
  Panel,
  PanelType,
  TextField,
  Dropdown,
  IDropdownOption,
  Stack,
  IStackTokens
} from '@fluentui/react';

export interface IReturnQueueListProps {
  items: IReturnRequest[];
  inventoryItems: IInventoryItem[];
  loading: boolean;
  onApprove: (item: IReturnRequest, remarks: string) => Promise<void>;
  onReject: (item: IReturnRequest, remarks: string) => Promise<void>;
  onComplete: (item: IReturnRequest, status: 'Available' | 'Under Repair' | 'Retired', remarks: string) => Promise<void>;
}

const stackTokens: IStackTokens = { childrenGap: 15 };

export const ReturnQueueList: React.FC<IReturnQueueListProps> = (props) => {
  const [activeRequest, setActiveRequest] = React.useState<IReturnRequest | undefined>(undefined);
  const [panelAction, setPanelAction] = React.useState<'Approve' | 'Reject' | 'Verify' | undefined>(undefined);
  const [remarks, setRemarks] = React.useState('');
  const [verificationStatus, setVerificationStatus] = React.useState<'Available' | 'Under Repair' | 'Retired'>('Available');
  const [submitting, setSubmitting] = React.useState(false);

  const openPanel = (request: IReturnRequest, action: 'Approve' | 'Reject' | 'Verify') => {
    setActiveRequest(request);
    setPanelAction(action);
    setRemarks('');
    setVerificationStatus('Available');
  };

  const closePanel = () => {
    setActiveRequest(undefined);
    setPanelAction(undefined);
    setRemarks('');
  };

  const handleAction = async () => {
    if (!activeRequest || !panelAction) return;
    try {
      setSubmitting(true);
      if (panelAction === 'Approve') {
        await props.onApprove(activeRequest, remarks);
      } else if (panelAction === 'Reject') {
        await props.onReject(activeRequest, remarks);
      } else if (panelAction === 'Verify') {
        await props.onComplete(activeRequest, verificationStatus, remarks);
      }
      closePanel();
    } catch (e) {
      console.error(e);
    } finally {
      setSubmitting(false);
    }
  };

  const columns: IColumn[] = [
    { key: 'colKey', name: 'Return Request ID', fieldName: 'returnRequestKey', minWidth: 100, maxWidth: 120, isResizable: true },
    { key: 'colAssetId', name: 'Asset ID', fieldName: 'assetId', minWidth: 60, maxWidth: 80, isResizable: true },
    {
      key: 'colAssetName',
      name: 'Asset Name',
      minWidth: 120,
      maxWidth: 150,
      isResizable: true,
      onRender: (item: IReturnRequest) => {
        const asset = props.inventoryItems.find(i => i.id === item.assetId);
        return <span>{asset ? (asset.assetName || asset.title) : (item.assetName || 'Unknown Asset')}</span>;
      }
    },
    {
      key: 'colSerialNumber',
      name: 'Serial Number',
      minWidth: 100,
      maxWidth: 120,
      isResizable: true,
      onRender: (item: IReturnRequest) => {
        const asset = props.inventoryItems.find(i => i.id === item.assetId);
        return <span>{asset ? asset.serialNumber : (item.serialNumber || 'N/A')}</span>;
      }
    },
    { key: 'colEmployee', name: 'Employee', fieldName: 'employee', minWidth: 120, maxWidth: 150, isResizable: true },
    { key: 'colReason', name: 'Return Reason', fieldName: 'returnReason', minWidth: 150, maxWidth: 220, isResizable: true, isMultiline: true },
    { key: 'colDate', name: 'Request Date', fieldName: 'requestDate', minWidth: 90, maxWidth: 110, isResizable: true },
    {
      key: 'colStatus',
      name: 'Status',
      fieldName: 'status',
      minWidth: 90,
      maxWidth: 100,
      isResizable: true,
      onRender: (item: IReturnRequest) => {
        let backgroundColor = '#f3f4f6';
        let textColor = '#374151';
        if (item.status === 'Pending') {
          backgroundColor = '#ffedd5';
          textColor = '#9a3412';
        } else if (item.status === 'Approved') {
          backgroundColor = '#dbeafe';
          textColor = '#1e40af';
        } else if (item.status === 'Rejected') {
          backgroundColor = '#fee2e2';
          textColor = '#991b1b';
        } else if (item.status === 'Completed') {
          backgroundColor = '#dcfce7';
          textColor = '#166534';
        }

        return (
          <span style={{
            backgroundColor,
            color: textColor,
            padding: '4px 12px',
            borderRadius: '9999px',
            fontSize: '0.75rem',
            fontWeight: 600,
            display: 'inline-block'
          }}>
            {item.status}
          </span>
        );
      }
    },
    { key: 'colRemarks', name: 'Remarks / Comments', fieldName: 'managerRemarks', minWidth: 120, maxWidth: 200, isResizable: true, isMultiline: true },
    {
      key: 'colActions',
      name: 'Actions',
      minWidth: 180,
      maxWidth: 220,
      isResizable: true,
      onRender: (item: IReturnRequest) => {
        if (item.status === 'Pending') {
          return (
            <Stack horizontal tokens={{ childrenGap: 5 }}>
              <PrimaryButton
                text="Approve"
                onClick={() => openPanel(item, 'Approve')}
                styles={{ root: { backgroundColor: '#107c41', borderColor: '#107c41' } }}
              />
              <DefaultButton
                text="Reject"
                onClick={() => openPanel(item, 'Reject')}
                styles={{ root: { color: '#ef4444' } }}
              />
            </Stack>
          );
        } else if (item.status === 'Approved') {
          return (
            <PrimaryButton
              text="Verify & Complete"
              iconProps={{ iconName: 'ComplianceAudit' }}
              onClick={() => openPanel(item, 'Verify')}
            />
          );
        }
        return <span>No Action Required</span>;
      }
    }
  ];

  const dropdownOptions: IDropdownOption[] = [
    { key: 'Available', text: 'Available (Restock)' },
    { key: 'Under Repair', text: 'Under Repair (Maintenance)' },
    { key: 'Retired', text: 'Retired (Dispose)' }
  ];

  return (
    <div style={{ marginTop: '20px' }}>
      {props.loading ? (
        <p>Loading return requests...</p>
      ) : props.items.length === 0 ? (
        <p style={{ fontStyle: 'italic', color: 'var(--text-muted)' }}>No return requests active.</p>
      ) : (
        <DetailsList
          items={props.items}
          columns={columns}
          setKey="set"
          layoutMode={DetailsListLayoutMode.justified}
          selectionMode={SelectionMode.none}
        />
      )}

      {activeRequest && panelAction && (
        <Panel
          isOpen={!!activeRequest}
          onDismiss={closePanel}
          type={PanelType.medium}
          headerText={
            panelAction === 'Approve' ? 'Approve Return Request' :
            panelAction === 'Reject' ? 'Reject Return Request' :
            'Verify & Complete Asset Return'
          }
          closeButtonAriaLabel="Close"
        >
          <Stack tokens={stackTokens} style={{ marginTop: '20px' }}>
            <TextField
              label="Return Request ID"
              value={activeRequest.returnRequestKey}
              readOnly
              disabled
            />
            <TextField
              label="Employee"
              value={activeRequest.employee}
              readOnly
              disabled
            />
            <TextField
              label="Return Reason"
              value={activeRequest.returnReason}
              multiline
              readOnly
              disabled
            />

            {panelAction === 'Verify' && (
              <Dropdown
                label="Verify Physical Condition & Set Status"
                selectedKey={verificationStatus}
                options={dropdownOptions}
                onChange={(_, option) => setVerificationStatus(option?.key as any)}
                required
              />
            )}

            <TextField
              label="Remarks / Comments"
              multiline
              rows={4}
              value={remarks}
              onChange={(_, newValue) => setRemarks(newValue || '')}
              placeholder="Enter details or comments here..."
              required={panelAction === 'Reject'}
            />

            <Stack horizontal tokens={{ childrenGap: 10 }} style={{ marginTop: '20px' }}>
              <PrimaryButton
                text={
                  panelAction === 'Approve' ? 'Approve Return' :
                  panelAction === 'Reject' ? 'Reject Return' :
                  'Complete Verification'
                }
                onClick={handleAction}
                disabled={submitting || (panelAction === 'Reject' && !remarks.trim())}
              />
              <DefaultButton
                text="Cancel"
                onClick={closePanel}
                disabled={submitting}
              />
            </Stack>
          </Stack>
        </Panel>
      )}
    </div>
  );
};
